using ECMAScript;
using static ECMAScript.Vue3;

namespace Wiki;

public static partial class WikiHomeModule
{
    private static bool IsKnownPage(string currentPath)
        => GetPageIndex(currentPath) >= 0;

    private static int GetPageIndex(string currentPath)
    {
        if (currentPath == OverviewPath)
            return 0;

        if (currentPath == GettingStartedPath)
            return 1;

        if (currentPath == ContentModelPath)
            return 2;

        if (currentPath == HFunctionAuthoringPath)
            return 3;

        if (currentPath == DeploymentPath)
            return 4;

        return -1;
    }

    private static string GetPagePath(int pageIndex)
    {
        if (pageIndex == 0)
            return OverviewPath;

        if (pageIndex == 1)
            return GettingStartedPath;

        if (pageIndex == 2)
            return ContentModelPath;

        if (pageIndex == 3)
            return HFunctionAuthoringPath;

        if (pageIndex == 4)
            return DeploymentPath;

        return "";
    }

    private static string GetPageGroup(string currentPath)
    {
        var pageIndex = GetPageIndex(currentPath);
        if (pageIndex <= 2)
            return "Foundation";

        if (pageIndex == 3)
            return "Engineering";

        return "Operations";
    }

    private static string GetPageTitle(string currentPath)
    {
        var pageIndex = GetPageIndex(currentPath);
        if (pageIndex == 0)
            return "Overview";

        if (pageIndex == 1)
            return "Getting Started";

        if (pageIndex == 2)
            return "Content Model";

        if (pageIndex == 3)
            return "H-Function Authoring";

        return "Deployment";
    }

    private static string GetPageSummary(string currentPath)
    {
        var pageIndex = GetPageIndex(currentPath);
        if (pageIndex == 0)
            return "A production-oriented docs shell for Jazor, authored entirely with ECMAScript.Vue3 H functions.";

        if (pageIndex == 1)
            return "Run the site locally, understand the route model, and validate the emitted Wiki host end to end.";

        if (pageIndex == 2)
            return "Code-first page metadata, explicit sections, and a navigation contract that stays readable in C#.";

        if (pageIndex == 3)
            return "Why H functions are the production authoring surface for this Wiki, and the conventions that keep it maintainable.";

        return "Build outputs, fallback routing, smoke verification, and the static delivery contract for Wiki.";
    }

    private static string GetPageStatus(string currentPath)
    {
        var pageIndex = GetPageIndex(currentPath);
        if (pageIndex == 0)
            return "Real Project MVP";

        if (pageIndex == 1)
            return "Foundation";

        if (pageIndex == 2)
            return "Authoring";

        if (pageIndex == 3)
            return "Engineering";

        return "Operations";
    }

    private static string GetPreviousPath(string currentPath)
    {
        var pageIndex = GetPageIndex(currentPath);
        if (pageIndex <= 0)
            return "";

        return GetPagePath(pageIndex - 1);
    }

    private static string GetNextPath(string currentPath)
    {
        var pageIndex = GetPageIndex(currentPath);
        if (pageIndex < 0 || pageIndex >= 4)
            return "";

        return GetPagePath(pageIndex + 1);
    }

    private static IVNode TocRail(string currentPath)
    {
        var pageIndex = GetPageIndex(currentPath);
        if (pageIndex == 0)
        {
            return TocRail("On this page",
            [
                TocLink(OverviewPath, "what-ships-now", "What ships now"),
                TocLink(OverviewPath, "why-this-exists", "Why this exists"),
                TocLink(OverviewPath, "mvp-boundary", "MVP boundary"),
                TocLink(OverviewPath, "site-structure", "Site structure")
            ]);
        }

        if (pageIndex == 1)
        {
            return TocRail("On this page",
            [
                TocLink(GettingStartedPath, "boot-the-site", "Boot the site"),
                TocLink(GettingStartedPath, "route-model", "Route model"),
                TocLink(GettingStartedPath, "add-a-page", "Add a page"),
                TocLink(GettingStartedPath, "verify-the-result", "Verify the result")
            ]);
        }

        if (pageIndex == 2)
        {
            return TocRail("On this page",
            [
                TocLink(ContentModelPath, "page-contract", "Page contract"),
                TocLink(ContentModelPath, "navigation-contract", "Navigation contract"),
                TocLink(ContentModelPath, "editing-rules", "Editing rules")
            ]);
        }

        if (pageIndex == 3)
        {
            return TocRail("On this page",
            [
                TocLink(HFunctionAuthoringPath, "layout-composition", "Layout composition"),
                TocLink(HFunctionAuthoringPath, "production-rules", "Production rules"),
                TocLink(HFunctionAuthoringPath, "why-this-works", "Why this works")
            ]);
        }

        return TocRail("On this page",
        [
            TocLink(DeploymentPath, "build-output", "Build output"),
            TocLink(DeploymentPath, "route-fallback", "Route fallback"),
            TocLink(DeploymentPath, "operational-checks", "Operational checks")
        ]);
    }
}
